INSERT IGNORE INTO properties (pkey, grp, type, label, value_cs, value_en, sort) VALUES
('form.err_captcha', 'form', 'line', NULL, 'Ověření proti spamu se nepodařilo. Zkuste to prosím znovu, nebo nám zavolejte.', 'The spam check failed. Please try again or give us a call.', 1),
('form.recaptcha_note', 'form', 'line', NULL, 'Formulář chrání reCAPTCHA od Googlu – platí {privacy} a {terms} Googlu.', 'This form is protected by reCAPTCHA – Google {privacy} and {terms} apply.', 2),
('form.recaptcha_privacy', 'form', 'line', NULL, 'zásady ochrany soukromí', 'Privacy Policy', 3),
('form.recaptcha_terms', 'form', 'line', NULL, 'smluvní podmínky', 'Terms of Service', 4),
('mail.track_subject', 'mail', 'line', NULL, 'Vaše poptávka č. {id} – {site}', 'Your enquiry no. {id} – {site}', 5),
('mail.track_body', 'mail', 'text', NULL, 'Dobrý den,\n\nděkujeme za poptávku. Její stav, smlouvu o dílo a faktury najdete kdykoli na tomto odkazu:\n{url}\n\nOdkaz je jen pro vás – nikomu ho nepřeposílejte.\n\n{site}', 'Hello,\n\nthank you for your enquiry. You can check its status, the contract and invoices at any time here:\n{url}\n\nThis link is just for you – please do not forward it.\n\n{site}', 6),
('track.title_generic', 'track', 'line', NULL, 'Vaše poptávka', 'Your enquiry', 7),
('track.title', 'track', 'line', NULL, 'Poptávka č. {id}', 'Enquiry no. {id}', 8),
('track.lead', 'track', 'line', NULL, 'Odesláno {date}. Tady uvidíte, jak se vaše zakázka posouvá.', 'Sent on {date}. Here you can follow how your job is progressing.', 9),
('track.invalid', 'track', 'line', NULL, 'Odkaz je neplatný nebo už vypršel. Napište nám nebo zavolejte a pošleme vám nový.', 'This link is invalid or has expired. Contact us and we will send you a new one.', 10),
('track.status', 'track', 'line', NULL, 'Stav poptávky', 'Enquiry status', 11),
('track.documents', 'track', 'line', NULL, 'Smlouva a faktury', 'Contract and invoices', 12),
('track.no_documents', 'track', 'line', NULL, 'Smlouvu o dílo připravíme po zaměření a domluvě ceny. Jakmile bude hotová, najdete ji tady.', 'We prepare the contract after measuring and agreeing on the price. You will find it here.', 13),
('track.contract', 'track', 'line', NULL, 'Smlouva o dílo', 'Contract for work', 14),
('track.invoice', 'track', 'line', NULL, 'Faktura', 'Invoice', 15),
('track.invoice_deposit', 'track', 'line', NULL, 'Zálohová faktura', 'Deposit invoice', 16),
