('track.messages', 'track', 'line', NULL, 'Zprávy', 'Messages', 21),
('track.help', 'track', 'line', NULL, 'Máte dotaz? Odpovězte na náš e-mail nebo zavolejte:', 'Any questions? Reply to our e-mail or call:', 22),
